        "code": "import asyncio\nimport os\nfrom pathlib import Path\nfrom pydantic import BaseModel, Field\nfrom browser_use import Agent, Browser, BrowserProfile, Tools, ActionResult\nfrom browser_use.llm import ChatGoogle\n\n\nclass SupplierInvoiceRow(BaseModel):\n    invoice_code: str = Field(..., min_length=4)\n    amount_vnd: int = Field(..., ge=0)\n    due_date: str\n\n\ntools = Tools()\n\n\n@tools.action(\"Luu chung tu da trich xuat vao hang doi ERP sau khi xac thuc schema\")\nasync def push_invoice_to_erp(invoice: SupplierInvoiceRow) -> ActionResult:\n    # Gui ve noi bo qua API co xac thuc mTLS/JWT thay vi de trinh duyet goi truc tiep\n    print(f\"[ERP_INGEST] Da xac thuc hoa don {invoice.invoice_code}: {invoice.amount_vnd} VND\")\n    return ActionResult(extracted_content=f\"Da luu hoa don {invoice.invoice_code}\")\n\n\nasync def run_isolated_b2b_sync(tenant_id: str) -> None:\n    profile_dir = Path(f\"/tmp/browser_profiles/{tenant_id}\")\n    profile_dir.mkdir(parents=True, exist_ok=True)\n\n    browser = Browser(\n        browser_profile=BrowserProfile(\n            headless=True,\n            user_data_dir=str(profile_dir),\n            # Chan tuyet doi dieu huong ra ngoai domain nha cung cap de ngan SSRF/Prompt Injection\n            allowed_domains=[\"portal.nhacungcap-b2b.vn\"],\n            disable_security=False,\n        )\n    )\n\n    # LLM khong bao gio nhin thay gia tri that trong sensitive_data; runtime tu thay khi go input\n    sensitive_credentials = {\n        \"https://portal.nhacungcap-b2b.vn\": {\n            \"b2b_username\": os.environ[\"B2B_PORTAL_USER\"],\n            \"b2b_password\": os.environ[\"B2B_PORTAL_PASS\"],\n        }\n    }\n\n    llm = ChatGoogle(model=\"gemini-3.8-flash\", temperature=0.0)\n\n    task = (\n        \"1. Mo https://portal.nhacungcap-b2b.vn va dang nhap bang b2b_username, b2b_password. \"\n        \"2. Neu gap man hinh yeu cau OTP hoac xac minh nguoi dung, DUNG NGAY va bao cao trang thai can nguoi xu ly. \"\n        \"3. Vao muc Cong no thang hien tai, doc bang hoa don va goi push_invoice_to_erp cho tung dong.\"\n    )\n\n    agent = Agent(\n        task=task,\n        llm=llm,\n        browser=browser,\n        tools=tools,\n        sensitive_data=sensitive_credentials,\n        use_vision=False,  # Bat DOM-first de giam token; chi bat True neu UI qua phuc tap\n        max_actions_per_step=3,\n    )\n\n    try:\n        history = await agent.run(max_steps=15)\n        print(\"Trang thai hoan tat:\", history.final_result())\n    finally:\n        await browser.close()\n\n\nif __name__ == \"__main__\":\n    asyncio.run(run_isolated_b2b_sync(tenant_id=\"tenant_f1_01\"))\n"
