        "description": "Định nghĩa máy trạng thái duyệt Đề nghị mua hàng (PO): sử dụng Annotated reducer nối log kiểm toán, lưu checkpoint bền vững xuống PostgreSQL qua PostgresSaver, tạm dừng bằng interrupt() chờ CFO duyệt qua ZaloBot và khôi phục chính xác bằng Command(resume=...) theo thread_id.",
        "code": "import operator\nfrom typing import Annotated, Literal, TypedDict\nfrom langgraph.checkpoint.postgres import PostgresSaver\nfrom langgraph.graph import END, START, StateGraph\nfrom langgraph.types import Command, interrupt\n\n\nclass PurchaseOrderState(TypedDict):\n    po_id: str\n    vendor_name: str\n    amount_vnd: int\n    audit_logs: Annotated[list[str], operator.add]\n    approval_status: Literal[\"pending\", \"approved\", \"rejected\"]\n    approver_note: str\n\n\ndef verify_budget_and_vendor(state: PurchaseOrderState) -> dict:\n    # Mo phong kiem tra han muc va chong trung gia nha cung cap\n    log = f\"Da doi soat ngan sach cho {state['po_id']} - {state['vendor_name']} ({state['amount_vnd']:,} VND)\"\n    return {\"audit_logs\": [log]}\n\n\ndef route_after_verify(state: PurchaseOrderState) -> Literal[\"human_gate\", \"auto_commit\"]:\n    # PO tu 20 trieu tro len bat buoc tam dung cho phe duyet qua ZaloBot\n    if state[\"amount_vnd\"] >= 20_000_000:\n        return \"human_gate\"\n    return \"auto_commit\"\n\n\ndef human_approval_gate(state: PurchaseOrderState) -> dict:\n    # Khong dat side-effect (gui ZNS/ghi MISA) truoc interrupt() de dam bao idempotent\n    decision = interrupt({\n        \"action\": \"APPROVE_PO\",\n        \"po_id\": state[\"po_id\"],\n        \"amount_vnd\": state[\"amount_vnd\"],\n        \"vendor\": state[\"vendor_name\"],\n    })\n    status = \"approved\" if decision.get(\"approved\") else \"rejected\"\n    note = decision.get(\"note\", \"\")\n    return {\n        \"approval_status\": status,\n        \"approver_note\": note,\n        \"audit_logs\": [f\"Ket qua phe duyet con nguoi: {status} ({note})\"],\n    }\n\n\ndef commit_to_erp_and_misa(state: PurchaseOrderState) -> dict:\n    if state.get(\"approval_status\") == \"rejected\":\n        return {\"audit_logs\": [f\"Huy PO {state['po_id']} theo yeu cau lanh dao.\"]}\n    return {\n        \"approval_status\": \"approved\",\n        \"audit_logs\": [f\"Da ghi nhan PO {state['po_id']} vao ERP 5.0 & dong bo ke toan MISA.\"],\n    }\n\n\ndef build_po_graph(checkpointer: PostgresSaver):\n    builder = StateGraph(PurchaseOrderState)\n    builder.add_node(\"verify_budget\", verify_budget_and_vendor)\n    builder.add_node(\"human_gate\", human_approval_gate)\n    builder.add_node(\"auto_commit\", commit_to_erp_and_misa)\n\n    builder.add_edge(START, \"verify_budget\")\n    builder.add_conditional_edges(\"verify_budget\", route_after_verify)\n    builder.add_edge(\"human_gate\", \"auto_commit\")\n    builder.add_edge(\"auto_commit\", END)\n    return builder.compile(checkpointer=checkpointer)\n\n\n# Vi du chay & danh thuc bang thread_id tren PostgreSQL thuc\nDB_URI = \"postgresql://erp_owner:secret@localhost:5432/domation_erp?sslmode=disable\"\n\nwith PostgresSaver.from_conn_string(DB_URI) as checkpointer:\n    checkpointer.setup()  # Tao bang checkpoints tu dong o lan dau\n    graph = build_po_graph(checkpointer)\n    config = {\"configurable\": {\"thread_id\": \"po-2026-0842\"}}\n\n    # Luot 1: Chay den interrupt() roi ngu yen tren Postgres\n    paused_result = graph.invoke(\n        {\n            \"po_id\": \"PO-2026-0842\",\n            \"vendor_name\": \"In An Viet Phat\",\n            \"amount_vnd\": 45_000_000,\n            \"audit_logs\": [],\n            \"approval_status\": \"pending\",\n            \"approver_note\": \"\",\n        },\n        config=config,\n    )\n    print(\"Dang cho duyet:\", paused_result.get(\"__interrupt__\"))\n\n    # Luot 2 (vai gio hoac vai ngay sau khi CFO bam nut ZaloBot):\n    resumed = graph.invoke(\n        Command(resume={\"approved\": True, \"note\": \"CFO da duyet chi dot 1\"}),\n        config=config,\n    )\n    print(\"Hoan tat PO:\", resumed[\"audit_logs\"])\n"
